import{_ as i,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"R 树","description":"","frontmatter":{"title":"R 树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/r-tree.md","filePath":"cs/r-tree.md","lastUpdated":1789023840000}'),h={name:"cs/r-tree.md"};function m(B,a,_,A,u,R){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="r-树" tabindex="-1">R 树 <a class="header-anchor" href="#r-树" aria-label="Permalink to &quot;R 树&quot;">​</a></h1><div class="epigraph"><p>每个节点存若干子矩形的最小外包框；查询框与 MBR 不相交则整页剪掉，相交则下降——为磁盘页而不是为内存二分。</p><footer>—— 据 Guttman, R-Trees: A Dynamic Index Structure for Spatial Searching, SIGMOD 1984；Beckmann et al., R*-tree, SIGMOD 1990 整理</footer></div><p><a href="/cs/kd-tree">上一课</a> 适合内存点集，节点太瘦，外存一次 I/O 只比较一个分裂值。<a href="/cs/bplus-split">B+</a> 已说明页要高扇出。本课不轮换轴。缺口是 R 树：页内多条记录，各带最小外包矩形（MBR），插入选「扩大面积最小」的子树，溢出则分裂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>空间对象（点、框、多边形外包）要按页索引。查询矩形 \\(Q\\)：根到叶，只进入 \\(MBR\\cap Q\\neq\\emptyset\\) 的孩子。MBR 可重叠，故可能多路下降，最坏仍扫很多页。缺口不是新的几何谓词，而是<strong>把 B 树的页占用率思想搬到矩形键</strong>，分裂启发式决定重叠多少。</p><p><span class="marginnote">Guttman SIGMOD 1984。R* 调整插入与强制重插以减重叠。本课钉 MBR 与剪枝，不把 R* 全部规则抄成词条。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：与 \\(Q\\) 相交则递归。插入：从根选子树（最小面积增量等），叶满则分裂成两组，使两组 MBR 面积和或重叠小，再向上插索引项。删除：欠载则合并或再分配，类似 B+。</p>',8)),(e(),n(c,null,{default:r(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%E6%A1%86%20Q%22%5D%20--%3E%20MBR%5B%22%E5%AD%A9%E5%AD%90%20MBR%22%5D%0A%20%20MBR%20--%3E%20SKIP%5B%22%E4%B8%8D%E7%9B%B8%E4%BA%A4%3A%20%E5%89%AA%E6%9E%9D%22%5D%0A%20%20MBR%20--%3E%20DOWN%5B%22%E7%9B%B8%E4%BA%A4%3A%20%E4%B8%8B%E9%99%8D%2C%20%E5%8F%AF%E5%A4%9A%E8%B7%AF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 k-d：R 树允许 MBR 重叠、面向块；k-d 空间不相交、面向内存。与四叉树：规则网格分裂 vs 数据自适应矩形。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>I/O 次数 ≈ 访问节点数。重叠大则剪枝弱，这是调分裂的原因。并发与 B 树锁耦合类似，本课串行。不要把 R 树写成神经网络空间；就是外存空间索引。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Hilbert 打包的具体码（下一课空间填充曲线会给序），不写三维 GIS 全流程。点集规则划分可用四叉/八叉，不一定要 R。</p><p>后课默认：外存空间范围查询默认 R 树家族。规则空间二分用四叉树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>R 树：分页 MBR 树，查询靠框相交剪枝。</li><li>分裂启发式决定重叠；最坏可退化。</li><li>规则网格划分是四叉/八叉树。</li><li>出处：Guttman, <em>SIGMOD</em>, 1984；Beckmann et al., <em>SIGMOD</em>, 1990。</li></ul>',8))])}const D=i(h,[["render",m]]);export{f as __pageData,D as default};
